//! MCPWM1
//! Motor Control Pulse-Width Modulation 1

#![allow(dead_code)]

pub const BASE: u32 = 0x500c1000;

/// CLK_CFG Register
///
/// PWM clock prescaler register.
///
/// Address offset: 0x0000
///
/// ## Fields
///
/// - **CLK_PRESCALE** `[7:0]` (RW)
///
///   Configures the prescaler value of clock, so that the period of PWM_clk = 6.25ns * (PWM_CLK_PRESCALE + 1).
#[repr(transparent)]
pub struct ClkCfg {
    value: crate::common::VolatileCell<u32>,
}

impl core::ops::Deref for ClkCfg {
    type Target = crate::common::VolatileCell<u32>;
    #[inline(always)]
    fn deref(&self) -> &Self::Target {
        &self.value
    }
}

impl ClkCfg {
    // ======== Field Constants ========

    /// **CLK_PRESCALE**
    ///
    /// Configures the prescaler value of clock, so that the period of PWM_clk = 6.25ns * (PWM_CLK_PRESCALE + 1).
    ///
    /// Bits `[7:0]`, mask `0x000000ff`
    pub const CLK_PRESCALE_OFFSET: u32 = 0;
    pub const CLK_PRESCALE_MASK: u32 = 0x000000ff;

    // ======== Field Accessors ========

    /// **CLK_PRESCALE** `[7:0]` (RW)
    ///
    /// Configures the prescaler value of clock, so that the period of PWM_clk = 6.25ns * (PWM_CLK_PRESCALE + 1).
    #[inline(always)]
    pub fn clk_prescale(&self) -> u32 {
        (self.value.read_bits() & Self::CLK_PRESCALE_MASK) >> Self::CLK_PRESCALE_OFFSET
    }

    /// Write **CLK_PRESCALE** `[7:0]` (RW)
    ///
    /// Configures the prescaler value of clock, so that the period of PWM_clk = 6.25ns * (PWM_CLK_PRESCALE + 1).
    #[inline(always)]
    pub fn write_clk_prescale(&self, value: u32) {
        self.value.modify_bits(|r| {
            (r & !Self::CLK_PRESCALE_MASK)
                | ((value << Self::CLK_PRESCALE_OFFSET) & Self::CLK_PRESCALE_MASK)
        });
    }
}

