    // ======== Field Constants ========

    /// **TIMER_PHASE_DIRECTION**
    ///
    /// Configures the PWM timer%s's direction when timer%s mode is up-down mode.\\0: Increase\\1: Decrease
    ///
    /// Bits `[20:20]`, mask `0x00100000`
    pub const TIMER_PHASE_DIRECTION_OFFSET: u32 = 20;
    pub const TIMER_PHASE_DIRECTION_MASK: u32 = 0x00100000;
    pub const TIMER_PHASE_DIRECTION: u32 = 1 << 20;

    /// **TIMER_PHASE**
    ///
    /// Configures the phase for timer%s reload on sync event.
    ///
    /// Bits `[19:4]`, mask `0x000ffff0`
    pub const TIMER_PHASE_OFFSET: u32 = 4;
    pub const TIMER_PHASE_MASK: u32 = 0x000ffff0;

    /// **TIMER_SYNCO_SEL**
    ///
    /// Configures the selection of PWM timer%s sync_out.\\0: Sync_in\\1: TEZ\\2: TEP\\3: Invalid, sync_out selects noting
    ///
    /// Bits `[3:2]`, mask `0x0000000c`
    pub const TIMER_SYNCO_SEL_OFFSET: u32 = 2;
    pub const TIMER_SYNCO_SEL_MASK: u32 = 0x0000000c;

    /// **SW**
    ///
    /// Configures the generation of software sync. Toggling this bit will trigger a software sync.
    ///
    /// Bits `[1:1]`, mask `0x00000002`
    pub const SW_OFFSET: u32 = 1;
    pub const SW_MASK: u32 = 0x00000002;
    pub const SW: u32 = 1 << 1;

    /// **TIMER_SYNCI_EN**
    ///
    /// Configures whether or not to enable timer%s reloading with phase on sync input event is enabled.\\0: Disable\\1: Enable
    ///
    /// Bits `[0:0]`, mask `0x00000001`
    pub const TIMER_SYNCI_EN_OFFSET: u32 = 0;
    pub const TIMER_SYNCI_EN_MASK: u32 = 0x00000001;
    pub const TIMER_SYNCI_EN: u32 = 1 << 0;

    // ======== Field Accessors ========

